-- Tarifas de flete por courier para el cálculo en cotizaciones.
-- Starken: valores NETOS por tramo de peso facturable (max(peso, cm3/4000)).
--   Tramos > 100 kg son tarifas POR KILO (kg_100_499 / kg_499_1000) + fijo_adicional.
--   Los tramos planos ya incluyen el fijo adicional (informativo).
-- Blue Express: valores NETOS por tramo de peso físico (el tarifario
--   oficial del courier viene bruto/IVA incluido y se convierte ÷1,19).

create table if not exists public.fletes_tarifas_starken (
  id bigserial primary key,
  region text not null,
  localidad text not null,
  t_0_05 numeric not null default 0,
  t_05_15 numeric not null default 0,
  t_15_3 numeric not null default 0,
  t_3_6 numeric not null default 0,
  t_6_10 numeric not null default 0,
  t_10_20 numeric not null default 0,
  t_20_30 numeric not null default 0,
  t_30_40 numeric not null default 0,
  t_40_50 numeric not null default 0,
  t_50_60 numeric not null default 0,
  t_60_70 numeric not null default 0,
  t_70_80 numeric not null default 0,
  t_80_90 numeric not null default 0,
  t_90_100 numeric not null default 0,
  kg_100_499 numeric not null default 0,
  kg_499_1000 numeric not null default 0,
  fijo_adicional numeric not null default 0,
  unique (region, localidad)
);

create table if not exists public.fletes_tarifas_blue (
  id bigserial primary key,
  region text not null unique,
  xs numeric not null default 0,   -- 0 a 0.5 kg (neto)
  s numeric not null default 0,    -- 0.5 a 3 kg
  m numeric not null default 0,    -- 3 a 6 kg
  l numeric not null default 0,    -- 6 a 16 kg
  xl numeric not null default 0    -- 16 a 25 kg
);

alter table public.fletes_tarifas_starken enable row level security;
alter table public.fletes_tarifas_blue enable row level security;

-- Recarga idempotente del seed.
delete from public.fletes_tarifas_starken;
delete from public.fletes_tarifas_blue;














